const recording = (provider: AIProvider, sent: SendMessageParams[]): AIProvider => ({
  async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
    sent.push(params);
    yield* provider.sendMessage(params);
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

